<script setup lang="ts">const{bookmarks,pending,loadBookmarks,createCollection}=useAccount(),name=ref("");useHead({title:"نشان‌های من — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(()=>void loadBookmarks());async function create(){if(name.value.trim().length<2)return;await createCollection(name.value);name.value="";}</script>
<template><AccountShell title="نشان‌ها و مجموعه‌ها" description="آگهی‌های موردعلاقه را در مجموعه‌های جدا نگه دارید."><template #action><form class="inline-create" @submit.prevent="create"><input v-model="name" maxlength="60" placeholder="نام مجموعه" aria-label="نام مجموعه"><button class="button button-primary" type="submit">مجموعه جدید</button></form></template><UiState v-if="pending&&!bookmarks.collections.length" kind="loading" title="در حال دریافت نشان‌ها" description="مجموعه‌ها در حال بارگذاری هستند."/><BookmarkCollectionList v-else :collections="bookmarks.collections" :items="bookmarks.items"/></AccountShell></template>
